import React, { useState, useEffect } from 'react';

function App() {
  const [mekanlar, setMekanlar] = useState([]);
  const [favoriler, setFavoriler] = useState([]); 
  const [filtre, setFiltre] = useState('Hepsi');
  const [maxSure, setMaxSure] = useState('');

  // YENİ ÖZELLİK: Detay penceresi ve Favori Listesi için State'ler
  const [seciliMekan, setSeciliMekan] = useState(null); // Detay için
  const [listeAcik, setListeAcik] = useState(false);    // Favori listesi için

  useEffect(() => {
    fetch('http://localhost:5000/api/rota')
      .then(res => res.json())
      .then(data => setMekanlar(Array.isArray(data) ? data : []))
      .catch(err => console.error("Bağlantı Hatası:", err));
  }, []);

  const favoriEkleCikar = (e, mekan) => {
    e.stopPropagation(); // Kartın detayını açmayı engelle (sadece butona basınca)
    setFavoriler((prev) => {
      const aktifListe = Array.isArray(prev) ? prev : [];
      const varMi = aktifListe.some(f => f.id === mekan.id);
      return varMi 
        ? aktifListe.filter(f => f.id !== mekan.id)
        : [...aktifListe, { ...mekan, sure: Number(mekan.sure) || 0 }];
    });
  };

  const toplamSure = (favoriler || []).reduce((toplam, m) => toplam + (Number(m.sure) || 0), 0);

  const filtrelenmis = mekanlar.filter(m => {
    const katUygun = filtre === 'Hepsi' || m.kategori === filtre;
    const sureUygun = maxSure === '' || (Number(m.sure) || 0) <= Number(maxSure);
    return katUygun && sureUygun;
  });

  return (
    <div className="container">
      {/* --- GARANTİ ÇALIŞAN GÖMÜLÜ CSS --- */}
      <style>{`
        body { font-family: 'Poppins', sans-serif; background-color: #f8f9fa; margin: 0; padding: 20px; }
        .header { text-align: center; margin-bottom: 30px; color: #1a4d6e; }

        /* Kontrol Paneli */
        .controls { display: flex; justify-content: center; gap: 12px; margin-bottom: 30px; flex-wrap: wrap; }

        /* Özet Barı (Artık Tıklanabilir!) */
        .summary-bar { 
          background: #1a4d6e; color: white; padding: 15px 30px; 
          border-radius: 50px; display: flex; justify-content: space-around; 
          margin-bottom: 40px; font-weight: 600; cursor: pointer;
          transition: transform 0.2s; box-shadow: 0 4px 12px rgba(26, 77, 110, 0.3);
        }
        .summary-bar:hover { transform: scale(1.02); background: #163a52; }

        .grid { display: flex; flex-wrap: wrap; justify-content: center; gap: 25px; }

        /* --- KART TASARIMI --- */
        .card {
          width: 280px; background: white; border-radius: 20px;
          overflow: hidden; box-shadow: 0 5px 15px rgba(0,0,0,0.05);
          cursor: pointer; display: flex; flex-direction: column;
          transition: all 0.3s ease; border: 2px solid transparent; box-sizing: border-box;
        }
        .card:hover {
          transform: translateY(-5px); 
          border-color: #00c2cb;
          box-shadow: 0 12px 24px rgba(0, 194, 203, 0.15);
        }

        .card-image-container { height: 180px; position: relative; padding: 10px; }
        .card-img { width: 100%; height: 100%; object-fit: cover; border-radius: 15px; }
        .badge { position: absolute; top: 15px; right: 15px; background: rgba(0,0,0,0.6); color: white; padding: 4px 10px; border-radius: 8px; font-size: 11px; backdrop-filter: blur(4px); }
        .card-content { padding: 15px; flex-grow: 1; display: flex; flex-direction: column; justify-content: space-between; }

        /* --- YENİ MODERN BUTONLAR --- */
        .btn-action {
          width: 100%; padding: 10px; border-radius: 25px;
          border: 1px solid #1a4d6e; background: transparent;
          color: #1a4d6e; font-weight: 600; cursor: pointer;
          margin-top: 10px; transition: all 0.3s;
          display: flex; justify-content: center; align-items: center; gap: 8px;
        }
        .btn-action:hover { background: #1a4d6e; color: white; }

        .btn-remove { border-color: #e74c3c; color: #e74c3c; }
        .btn-remove:hover { background: #e74c3c; color: white; }

        /* --- MODAL (AÇILIR PENCERE) STİLLERİ --- */
        .modal-overlay {
          position: fixed; top: 0; left: 0; right: 0; bottom: 0;
          background: rgba(0,0,0,0.7); z-index: 1000;
          display: flex; justify-content: center; align-items: center;
          animation: fadeIn 0.3s;
        }
        .modal-content {
          background: white; padding: 30px; border-radius: 20px;
          max-width: 500px; width: 90%; position: relative;
          box-shadow: 0 10px 30px rgba(0,0,0,0.3);
          text-align: center;
          animation: slideUp 0.3s;
        }
        .close-btn {
          position: absolute; top: 15px; right: 15px;
          background: #f1f1f1; border: none; width: 30px; height: 30px;
          border-radius: 50%; cursor: pointer; font-weight: bold;
        }

        /* Liste Modalı Özel */
        .liste-item { display: flex; justify-content: space-between; padding: 10px; border-bottom: 1px solid #eee; }

        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        @keyframes slideUp { from { transform: translateY(20px); } to { transform: translateY(0); } }

      `}</style>

      {/* --- BAŞLIK --- */}
      <div className="header">
        <h1>🌴 Antalya Rota Asistanı</h1>
        <p style={{color: '#666'}}>Akula Holiday Staj Projesi</p>
      </div>

      {/* --- FİLTRELER --- */}
      <div className="controls">
        <input type="number" className="search-input" placeholder="Maks. Süre (dk)" 
          value={maxSure} onChange={(e) => setMaxSure(e.target.value)} 
          style={{padding: '10px 20px', borderRadius: '25px', border: '1px solid #ddd', outline: 'none'}} />

        {['Hepsi', 'Tarih', 'Doğa', 'Yemek', 'Eğlence'].map(k => (
          <button key={k} 
            onClick={() => setFiltre(k)}
            style={{
              padding: '8px 20px', borderRadius: '25px', border: 'none', cursor: 'pointer',
              background: filtre === k ? '#1a4d6e' : 'white', 
              color: filtre === k ? 'white' : '#666',
              boxShadow: '0 2px 5px rgba(0,0,0,0.05)'
            }}
          >
            {k}
          </button>
        ))}
      </div>

      {/* --- TIKLANABİLİR ÖZET BARI --- */}
      <div className="summary-bar" onClick={() => setListeAcik(true)} title="Listeyi görmek için tıkla">
        <span>🎒 Rota Listem: {favoriler.length} Mekan</span>
        <span>⏱️ Toplam: {Math.floor(toplamSure / 60)}sa {toplamSure % 60}dk</span>
      </div>

      {/* --- KARTLAR --- */}
      <div className="grid">
        {filtrelenmis.map(m => {
          const seciliMi = favoriler?.some(f => f.id === m.id);
          return (
            <div key={m.id} className="card" onClick={() => setSeciliMekan(m)}>
              <div className="card-image-container">
                <img src={m.resim} alt={m.ad} className="card-img" />
                <span className="badge">{m.kategori}</span>
              </div>
              <div className="card-content">
                <h3 style={{margin: '0 0 5px 0', color: '#1a4d6e'}}>{m.ad}</h3>
                <div style={{fontSize: '13px', color: '#7f8c8d', display: 'flex', justifyContent: 'space-between'}}>
                   <span>📍 {m.bolge}</span>
                   <span>⏳ {m.sure} dk</span>
                </div>
                {/* Butona tıklayınca e.stopPropagation ile kart açılmasını engelliyoruz */}
                <button 
                  className={`btn-action ${seciliMi ? 'btn-remove' : ''}`}
                  onClick={(e) => favoriEkleCikar(e, m)}
                >
                  {seciliMi ? 'Rotadan Çıkar ✕' : 'Rotaya Ekle ➜'}
                </button>
              </div>
            </div>
          );
        })}
      </div>

      {/* --- 1. DETAY PENCERESİ (MODAL) --- */}
      {seciliMekan && (
        <div className="modal-overlay" onClick={() => setSeciliMekan(null)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <button className="close-btn" onClick={() => setSeciliMekan(null)}>✕</button>
            <img src={seciliMekan.resim} alt={seciliMekan.ad} style={{width: '100%', borderRadius: '15px', height: '200px', objectFit: 'cover'}} />
            <h2 style={{color: '#1a4d6e', marginTop: '15px'}}>{seciliMekan.ad}</h2>
            <p style={{color: '#666'}}>
              Bu mekan <strong>{seciliMekan.bolge}</strong> bölgesinde yer alıyor. 
              Gezmek için yaklaşık <strong>{seciliMekan.sure} dakika</strong> ayırmanızı öneririz.
            </p>
            <div style={{display: 'flex', justifyContent: 'center', gap: '10px', marginTop: '20px'}}>
              <span style={{background: '#e0f2f1', color: '#009688', padding: '5px 15px', borderRadius: '15px', fontSize: '14px'}}>
                {seciliMekan.kategori}
              </span>
            </div>
          </div>
        </div>
      )}

      {/* --- 2. FAVORİ LİSTESİ PENCERESİ --- */}
      {listeAcik && (
        <div className="modal-overlay" onClick={() => setListeAcik(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <button className="close-btn" onClick={() => setListeAcik(false)}>✕</button>
            <h3 style={{color: '#1a4d6e'}}>🎒 Rota Listeniz</h3>
            <div style={{maxHeight: '300px', overflowY: 'auto', textAlign: 'left', marginTop: '15px'}}>
              {favoriler.length === 0 ? (
                <p style={{textAlign: 'center', color: '#999'}}>Henüz bir yer eklemediniz.</p>
              ) : (
                favoriler.map(fav => (
                  <div key={fav.id} className="liste-item">
                    <span>{fav.ad}</span>
                    <span style={{color: '#999', fontSize: '14px'}}>{fav.sure} dk</span>
                  </div>
                ))
              )}
            </div>
            {favoriler.length > 0 && (
              <div style={{marginTop: '20px', borderTop: '1px solid #eee', paddingTop: '10px'}}>
                <strong>Toplam Süre: {Math.floor(toplamSure / 60)} saat {toplamSure % 60} dakika</strong>
              </div>
            )}
          </div>
        </div>
      )}

    </div>
  );
}

export default App;
